<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {productCatalogAPI,type ProductCatalogItem} from '@/api/productCatalog'
import {useAdminAuthStore} from '@/stores/auth'
const auth=useAdminAuthStore();const rows=ref<ProductCatalogItem[]>([]);const loading=ref(false);const error=ref('');const search=ref('');const active=ref('all');const page=ref(1);const total=ref(0);const includeInactive=ref(false);const editing=ref<number|null>(null);const draft=ref({cost_price:'',sale_price:'',follow_product_price:true})
const readOnly=computed(()=>!auth.isSuper);const title=(row:ProductCatalogItem)=>row.title?.['zh-CN']||Object.values(row.title||{})[0]||row.product_slug;const money=(value:unknown)=>Number(value||0).toFixed(2)
async function load(){loading.value=true;error.value='';try{const res=await productCatalogAPI.list({page:page.value,page_size:20,search:search.value,product_active:active.value});rows.value=res.data.data||[];total.value=res.data.pagination?.total||0}catch(e:any){error.value=e.message||'加载失败'}finally{loading.value=false}}
async function sync(){if(readOnly.value)return;loading.value=true;try{await productCatalogAPI.sync(includeInactive.value);await load()}catch(e:any){error.value=e.message||'同步失败'}finally{loading.value=false}}
function start(row:ProductCatalogItem){editing.value=row.id;draft.value={cost_price:String(row.cost_price||''),sale_price:String(row.sale_price||''),follow_product_price:row.follow_product_price}}
async function save(row:ProductCatalogItem){loading.value=true;try{await productCatalogAPI.update(row.id,{cost_price:draft.value.cost_price,sale_price:draft.value.sale_price,follow_product_price:draft.value.follow_product_price});editing.value=null;await load()}catch(e:any){error.value=e.message||'保存失败'}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="catalog"><header><h1>商品清单</h1><p>按 SKU 管理成本、售价、利润和库存。商品下架后清单仍保留；同步不会覆盖手工价格。</p></header><div class="toolbar"><input v-model="search" placeholder="搜索商品或 SKU" @keyup.enter="page=1;load()"><select v-model="active" @change="page=1;load()"><option value="all">全部状态</option><option value="1">在售</option><option value="0">已下架</option></select><button :disabled="loading" @click="page=1;load()">查询</button><button v-if="auth.isSuper" :disabled="loading" @click="sync">同步当前在售</button><label v-if="auth.isSuper"><input v-model="includeInactive" type="checkbox">同步已下架</label></div><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>商品 / SKU</th><th>状态</th><th>商品当前价</th><th>成本</th><th>售价</th><th>利润</th><th>利润率</th><th>库存</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{title(row)}}</strong><small>{{row.product_slug}} · {{row.sku_code}}</small></td><td>{{row.product_active&&row.sku_active?'在售':'已下架'}}</td><td>{{money(row.product_price)}}</td><td v-if="editing!==row.id">{{money(row.cost_price)}}</td><td v-else><input v-model="draft.cost_price" type="number" min="0" step="0.01"></td><td v-if="editing!==row.id">{{money(row.effective_sale_price)}}</td><td v-else><input v-model="draft.sale_price" type="number" min="0" step="0.01" :disabled="draft.follow_product_price"></td><td>{{money(row.profit_amount)}}</td><td>{{Number(row.profit_rate||0).toFixed(2)}}%</td><td>{{row.inventory<0?'无限':row.inventory}}</td><td v-if="!readOnly&&editing!==row.id"><button @click="start(row)">编辑</button></td><td v-else-if="!readOnly"><label><input v-model="draft.follow_product_price" type="checkbox">跟随商品价</label><button @click="save(row)">保存</button></td><td v-else>只读</td></tr></tbody></table></div><div class="pager"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>第{{page}}页 / {{total}}条</span><button :disabled="page*20>=total" @click="page++;load()">下一页</button></div></section></template>
<style scoped>.catalog{display:grid;gap:18px;max-width:1500px;margin:0 auto;min-width:0}h1{font-size:26px;font-weight:700}header p,small{display:block;color:hsl(var(--muted-foreground));line-height:1.7;font-size:13px}.toolbar,.pager{display:flex;align-items:center;gap:10px;flex-wrap:wrap}input,select,button{border:1px solid hsl(var(--border));border-radius:8px;padding:8px 10px;background:hsl(var(--background));color:hsl(var(--foreground));font:inherit}button{cursor:pointer}button:disabled{opacity:.45}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:12px;border-bottom:1px solid hsl(var(--border));text-align:left}.error{color:#b91c1c}</style>
